{"content":"import unittest

from connect import ConnectGame


class ConnectGameTest(unittest.TestCase):
    def test_empty_boards(self):
        for board in ("", "\n  \n", ".", ". .\n . ."):
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_single_stones(self):
        for player in ("X", "O"):
            with self.subTest(player=player):
                self.assertEqual(ConnectGame(player).get_winner(), player)

    def test_rectangular_boards(self):
        cases = (
            ("X X X X\n O O . .", "X"),
            ("O X\n O X\n O .\n O X", "O"),
            ("X X X", "X"),
            ("O\n O\n O", "O"),
            (". O .", "O"),
            (".\n X\n .", "X"),
        )
        for board, winner in cases:
            with self.subTest(board=board):
                self.assertEqual(ConnectGame(board).get_winner(), winner)

    def test_allowed_diagonal_connections(self):
        for player in ("X", "O"):
            board = f". . {player}\n . {player} .\n {player} . ."
            with self.subTest(player=player):
                self.assertEqual(ConnectGame(board).get_winner(), player)

    def test_disallowed_diagonal_connections(self):
        for player in ("X", "O"):
            board = f"{player} . .\n . {player} .\n . . {player}"
            with self.subTest(player=player):
                self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_connection_across_wrong_sides_does_not_win(self):
        board = ". O . X .\n . X X O .\n  O O O X .\n   . X O X O\n    X O O O X"
        self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_all_starting_stones_are_explored(self):
        board = "X . . .\n . . . .\n X X X X"
        self.assertEqual(ConnectGame(board).get_winner(), "X")

    def test_cycles_without_a_winner(self):
        board = "X X .\n X X .\n . . ."
        self.assertEqual(ConnectGame(board).get_winner(), "")

    def test_path_can_backtrack(self):
        board = "X . X X X\n X . X . .\n X X X . ."
        self.assertEqual(ConnectGame(board).get_winner(), "X")

    def test_whitespace_and_repeated_calls(self):
        game = ConnectGame("\n  X\tX X  \n   . O .\n")
        self.assertEqual(game.get_winner(), "X")
        self.assertEqual(game.get_winner(), "X")

    def test_long_path_does_not_require_recursion(self):
        self.assertEqual(ConnectGame(" ".join(["X"] * 2000)).get_winner(), "X")


if __name__ == "__main__":
    unittest.main()
